   0 import { injectable } from "tsyringe";
   1 import { IAiService } from "../../domain/services/IAiService";
   2 import { ai } from "./Genkit";
   3 import { executeWithQueue } from "./model-request-queue";
   4 import { selectModel } from "./model-selector";
   5 import { generateRequestId } from "./model-performance-monitor";
   6 
   7 import { Result } from "@/infrastructure/utils/result";
   8 import { AiError } from "../../domain/errors/AiErrors";
   9 import { generateChapterContentWithRAG } from "../flows/generation/generate-chapter-content-rag";
  10 import { generateReportSectionWithRAG } from "../flows/generation/generate-report-section-rag";
  11 
  12 @injectable()
  13 export class GenkitAiService implements IAiService {
  14     async generateText(prompt: string, options?: any): Promise<Result<string, AiError>> {
  15         try {
  16             const result = await ai.generate({
  17                 prompt,
  18                 ...options
  19             });
  20             return Result.ok(result.text);
  21         } catch (error: any) {
  22             return Result.fail(AiError.generationFailed(error.message));
  23         }
  24     }
  25 
  26     async runFlow<TInput, TOutput>(flow: any, input: TInput, flowName?: string): Promise<Result<TOutput, AiError>> {
  27         try {
  28             if (!flowName) {
  29                 const data = await flow(input);
  30                 return Result.ok(data);
  31             }
  32             
  33             const model = selectModel({ flowName });
  34             const result = await executeWithQueue(
  35                 generateRequestId(),
  36                 model,
  37                 flowName,
  38                 () => flow(input)
  39             );
  40             return Result.ok(result as TOutput);
  41         } catch (error: any) {
  42             console.warn(`Queue or flow execution failed for ${flowName || 'unnamed flow'}`, error);
  43             try {
  44                 const result = await flow(input);
  45                 return Result.ok(result);
  46             } catch (fallbackError: any) {
  47                 return Result.fail(AiError.generationFailed(fallbackError.message));
  48             }
  49         }
  50     }
  51 
  52     async retrieveContext(query: string, options?: any): Promise<Result<{ context: string; sources: any[] }, AiError>> {
  53         try {
  54             // Dynamic import to avoid circular dependencies with RAG module
  55             const { retrieveContext } = require('@/modules/rag/infrastructure/retrieval');
  56             const result = await retrieveContext(query, options);
  57             return Result.ok(result);
  58         } catch (error: any) {
  59             return Result.fail(AiError.internal(error.message));
  60         }
  61     }
  62 
  63     async generateChapterWithRAG(input: any): Promise<Result<any, AiError>> {
  64         try {
  65             const result = await generateChapterContentWithRAG(input);
  66             return Result.ok(result);
  67         } catch (error: any) {
  68             return Result.fail(AiError.generationFailed(error.message));
  69         }
  70     }
  71 
  72     async generateSectionWithRAG(input: any): Promise<Result<any, AiError>> {
