   2 import { useAuth } from '@/context/AuthContext';
   3 import { toast } from '@/hooks';
   4 import { WritingToolsApiClient } from '@/modules/ai/adapters/api-client/WritingToolsApiClient';
   5 import { useMutation, type UseMutationOptions } from '@tanstack/react-query';
   6 import { container } from '@/infrastructure/di/container';
   7 
   8 export function useWritingTool<TData = unknown, TVariables = any>(
   9   endpoint: string,
  10   options?: Omit<UseMutationOptions<TData, Error, TVariables>, 'mutationFn'>,
  11 ) {
  12   const { refetchUser } = useAuth();
  13 
  14   return useMutation<TData, Error, TVariables>({
  15     mutationFn: async (data: TVariables) => {
  16       const client = container.resolve(WritingToolsApiClient);
  17       const result = await client.writingToolApi<TVariables, TData>(endpoint, data);
  18       if (result.isFailure) throw result.error;
  19       return result.getValue();
  20     },
  21     onSuccess: (data, variables, context) => {
  22       refetchUser();
  23       if (options?.onSuccess) {
  24         // @ts-expect-error - Type mismatch with TanStack Query callback signature
  25         options.onSuccess(data, variables, context);
  26       }
  27     },
  28     onError: (error: Error, variables, context) => {
  29       toast({
  30         title: 'An Error Occurred',
  31         description: error.message,
  32         variant: 'destructive',
  33       });
  34       if (options?.onError) {
  35         // @ts-expect-error - Type mismatch with TanStack Query callback signature
  36         options.onError(error, variables, context);
  37       }
  38     },
  39     ...options,
  40   });
  41 }
  42 
````

